"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9365"],{82954(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.descricao_tamanho","status":422,"titulo":"Tamanho da descri\xe7\xe3o do valor de dom\xednio inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.descricao_tamanho","requisitos":[],"oQueAconteceu":["A descri\xe7\xe3o enviada para um valor de fato do cat\xe1logo tem mais de 500 caracteres, ao acrescentar o valor (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`) ou ao corrigi-lo (`PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`). Os espa\xe7os nas pontas s\xe3o desconsiderados antes da confer\xeancia. A descri\xe7\xe3o \xe9 o nome curto da op\xe7\xe3o, n\xe3o um par\xe1grafo.","A recusa vem na lista `errors` da resposta, com `field` igual a `descricao`. Se o corpo tiver outros problemas, cada um vem numa entrada pr\xf3pria da mesma resposta, e nada \xe9 gravado. A busca do fato vem antes da confer\xeancia do corpo, e na corre\xe7\xe3o a busca do valor tamb\xe9m: um `{id}` ou um `{codigo}` que n\xe3o existe responde como n\xe3o encontrado, e n\xe3o com esta recusa."],"comoResolver":["Reduza a descri\xe7\xe3o a at\xe9 500 caracteres. O que o candidato precisa saber sobre a op\xe7\xe3o, al\xe9m do nome curto, vai na orienta\xe7\xe3o do valor, que aparece abaixo dela."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);